PRAGMA journal_mode=WAL;
PRAGMA busy_timeout=10000;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, student_no TEXT UNIQUE NOT NULL, name TEXT NOT NULL, gender TEXT, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'MEMBER', member_status TEXT NOT NULL DEFAULT 'UNCONFIRMED', approved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS seats (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE NOT NULL, row_no INTEGER NOT NULL, col_no INTEGER NOT NULL, area TEXT NOT NULL DEFAULT '主实验室', type TEXT NOT NULL DEFAULT 'FIXED', status TEXT NOT NULL DEFAULT 'AVAILABLE', occupant_id INTEGER, review_mode INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS seat_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, seat_id INTEGER NOT NULL, reason TEXT, status TEXT NOT NULL DEFAULT 'PENDING', reviewed_by INTEGER, review_note TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS seat_bookings (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, seat_id INTEGER NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reports (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, week_start TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', sections_json TEXT NOT NULL, submitted_at TEXT);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, read_flag INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_id INTEGER, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS seat_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, seat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, ended_at TEXT, end_reason TEXT);
CREATE TABLE IF NOT EXISTS reviews (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL, seat_id INTEGER, reason TEXT NOT NULL, requirements TEXT, start_at TEXT NOT NULL, end_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PLANNED', result TEXT, decision_note TEXT, created_by INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS weekly_report_tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, review_id INTEGER NOT NULL, member_id INTEGER NOT NULL, period_index INTEGER NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'OPEN', UNIQUE(review_id, period_index));
CREATE TABLE IF NOT EXISTS weekly_reports (id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL UNIQUE, user_id INTEGER NOT NULL, sections_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', submitted_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS special_circumstances (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, type TEXT NOT NULL, start_at TEXT NOT NULL, end_at TEXT NOT NULL, description TEXT NOT NULL, evidence_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, member_id INTEGER NOT NULL, review_id INTEGER, content TEXT NOT NULL, created_by INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_users_approved ON users(approved, member_status);
CREATE INDEX IF NOT EXISTS idx_seat_booking_window ON seat_bookings(seat_id, status, start_at, end_at);
CREATE INDEX IF NOT EXISTS idx_review_member ON reviews(member_id, status);
CREATE INDEX IF NOT EXISTS idx_task_member ON weekly_report_tasks(member_id, due_at);
CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, type TEXT NOT NULL, description TEXT NOT NULL, requirements TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), deadline TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'RECRUITING', created_by INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_applications (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id), user_id INTEGER NOT NULL REFERENCES users(id), reason TEXT NOT NULL, skills TEXT NOT NULL, availability TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'PENDING', review_note TEXT NOT NULL DEFAULT '', reviewed_by INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS idx_project_pending ON project_applications(project_id,user_id) WHERE status='PENDING';
CREATE TABLE IF NOT EXISTS project_members (project_id INTEGER NOT NULL REFERENCES projects(id), user_id INTEGER NOT NULL REFERENCES users(id), joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(project_id,user_id));
CREATE INDEX IF NOT EXISTS idx_project_app_user ON project_applications(user_id,project_id);
